insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('griindunnastog', 'Griindunnastog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Gründonnerstag', '[{"kategorie": "wörtlich", "text": "\"Gründonnerstag\" (vom mittelhochdeutschen \"grîndonrestag\"=\"der weinende Donnerstag\" [von \"grînen\"=\"weinen\"])"}, {"kategorie": "rel.", "text": "\"Tag des Letzten Abendmahls\" (bedeutender Tag in der christlichen Karwoche, der immer am Donnerstag vor Ostern gefeiert wird), \"Tag der Fußwaschung\" (an dem Jesus ein Zeichen der Demut und Liebe durch die Fußwaschung setzte), \"Tag des Verrats durch Judas\", \"Beginn des österlichen Triduums\" (theologisch-liturgischer Ausdruck für den Start der drei österlichen Tage von Gründonnerstag bis zur Osternacht)"}]'::jsonb, 'Aum Griindunnastog bock ma imma a aafochs Flaadnbrood!'),
  ('koafreidog', 'Koafreidog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Karfreitag', '[{"kategorie": "wörtlich", "text": "\"Karfreitag\" (vom mittelhochdeutschen \"kârvrîtag\"=\"Karfreitag\" [vom althochdeutschen „kara“=\"Klage, Trauer, Kummer\")"}, {"kategorie": "rel.", "text": "\"Heiliger Freitag\", \"Tag des Leidens Christi\" (der letzte Freitag vor dem [[Ostersonntag]] - kein Tag des Festes, sondern der Erinnerung, Stille und Hoffnung), \"Tag der Kreuzigung\" (erinnert an das größte Opfer im christlichen Glauben – den Tod Jesu –, der den Weg zur Erlösung ebnet), \"Tag der Passion des Herrn\""}]'::jsonb, 'Koafreidog is da Toog, aun dem de Glockn schweing!'),
  ('koasaumsdog', 'Koasaumsdog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Karsamstag', '[{"kategorie": "wörtlich", "text": "\"Karsamstag\" (vom mittelhochdeutschen \"kârsâmztac\"=\"Karsamstag\" [vom althochdeutschen „kara“=\"Klage, Trauer, Kummer\")"}, {"kategorie": "rel.", "text": "\"Heiliger Samstag\" (der letzte Tag der Karwoche und zugleich der dritte Tag der sogenannten „stillen Tage“ [nach Gründonnerstag und Karfreitag]), \"Tag der Grabesruhe\" (der letzte Samstag vor dem [[Ostersonntag]] - kein Tag des Festes, sondern der Erinnerung, Stille und Hoffnung), \"Ostervigil-Tag\" (bezogen auf die Osternacht [Vigil], die am Abend des Karsamstags beginnt)"}]'::jsonb, 'Da Koasaumsdog schdeed zwischn Jesu Tod und seina Aufaschdeehung!'),
  ('koawochn', 'Koawochn', 'die', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Karwoche', '[{"kategorie": "wörtlich", "text": "\"Karwoche\" (vom mittelhochdeutschen \"kârwoche\"=\"Karwoche\" [vom althochdeutschen „kara“=\"Klage, Trauer, Kummer\")"}, {"kategorie": "rel.", "text": "\"Heilige Woche\" (die letzte Woche der Fastenzeit im christlichen Kirchenjahr zwischen Palmsonntag und Karsamstag), \"Passionswoche\" (in welcher der Leiden Jesu gedacht wird), \"österliche Bußwoche\""}]'::jsonb, 'In da Koawochn begleitn de Christn in Jesus auf sein Weeg zum Kreiz!'),
  ('oostafeia', 'Oostafeia', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Osterfeuer', '[{"kategorie": "wörtlich", "text": "\"Osterfeuer\" (vom mittelhochdeutschen \"ōsterfiur\"=\"Osterfeuer\")"}, {"kategorie": "rel.", "text": "\"Feuer der Osternacht\" (wird in der Nacht zum Ostersonntag entzündet - und hieraus dann die Osterkerze, welche das Licht Christi symbolisiert, das die Dunkelheit des Todes und der Sünde überwindet), \"Auferstehungsfeuer\", \"Heiliges Osterlicht\" (dieses Licht wird in die dunkle Kirche getragen – ein Symbol für das Osterwunder ), \"Licht der Hoffnung\" (vom Tod ins Leben, von der Nacht ins Licht, von der Trauer zur Hoffnung)"}]'::jsonb, 'Im Oostafeia faungds neiche Liachd au, des Christus ois Liachd da Wööd vaköapad!'),
  ('oostalaumm', 'Oostalaumm', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Osterlamm', '[{"kategorie": "wörtlich", "text": "\"Osterlamm\" (vom mittelhochdeutschen \"ōstirlām\"=\"Osterlamm\")"}, {"kategorie": "rel.", "text": "\"Lamm Gottes\" (steht für Unschuld, Opfer, Erlösung – und weist auf Christus als das „Lamm Gottes“ hin, das durch seinen Tod die Sünde der Welt hinweg nimmt), (lateinisch): \"Agnus Dei\" (vgl. Joh 1,29: \"Siehe, das Lamm Gottes, das hinwegnimmt die Sünde der Welt\"), \"Osteropfer\" (symbolisiert Jesus Christus, der nach christlichem Glauben am Kreuz geopfert wurde, um die Menschheit zu erlösen), \"Paschalamm\" (das jüdische Pessachlamm, das beim Auszug aus Ägypten geopfert wurde - vgl. 2. Mose 12: Dieses Pessachopfer wurde im Neuen Testament auf Christus gedeutet)"}, {"kategorie": "", "text": "\"Osterlamm aus Biskuit oder Rührteig\" (Gebäcklamm), \"Festtagslamm\" (kulinarischer Ausdruck für das traditionelle Ostergericht), \"Osterbraten\" (Lamm als Speise)"}]'::jsonb, 'Wia segnan jeds Joa unsa Ostalaumm bei da Mess in da Oostanochd!'),
  ('oostaeia', 'Oostaeia', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostereia', '[{"kategorie": "wörtlich", "text": "\"Osterei\" (vom mittelhochdeutschen \"ōsterei\"=\"Osterei\")"}, {"kategorie": "rel.", "text": "\"Ei des Lebens\" (steht für neues Leben, Hoffnung und die Auferstehung Jesu Christi. Obwohl das Ei selbst kein biblisches Symbol ist, wurde es in der frühen Christenheit als Zeichen des neuen Lebens in Christus verstanden. Die geschlossene Eierschale, aus der Leben hervorgeht, wurde als Bild für das leere Grab Jesu interpretiert. Besonders in der orthodoxen Kirche wurde das rote Osterei zum Symbol für das vergossene Blut Christi und seine Auferstehung)"}, {"kategorie": "", "text": "bemaltes oder gefärbtes Ei (Symbol für neues Leben, Auferstehung und Frühling - es gehört zu den bekanntesten und ältesten Osterbräuchen im Christentum und in der europäischen Kulturgeschichte)"}]'::jsonb, 'Im Oostaeia liigd de schdülle Vaheissung des Leebms, des ausn Tood eawocht!'),
  ('oostan', 'Oostan', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostern', '[{"kategorie": "wörtlich", "text": "\"Osterfest\" (vom mittelhochdeutschen \"ōsteren\"=\"Ostern\")"}, {"kategorie": "rel.", "text": "\"Ostern\" (zentrales Hochfest des Christentums, an dem die Auferstehung Jesu Christi von den Toten gefeiert wird), \"das christliche Fest der Auferstehung\" (gilt als Sieg des Lebens über den Tod, der Höhepunkt des Kirchenjahres und der Grundstein des christlichen Glaubens), \"Auferstehungsfest\", \"Paschafest\" (im Judentum: das Pessachfest – zur Erinnerung an den Auszug der Israeliten aus Ägypten)"}]'::jsonb, 'Oostan vakündet in Siig des Leebms iwan Tood!'),
  ('weinochtn', 'Weinochtn', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Weihnachten', '[{"kategorie": "wörtlich", "text": "\"Weihnachtsfest\" (vom mittelhochdeutschen \"wîhen nahten\"=\"Weihnachten\")"}, {"kategorie": "rel.", "text": "\"Weihnachten\" (christliche Hochfest, an dem die Geburt Jesu Christi gefeiert wird), \"Geburtsfest Christi\" (erinnert an die Geburt des Friedensbringers, feiert die Gegenwart Gottes in der Welt und ruft zur Nächstenliebe, Hoffnung und Gemeinschaft auf), \"Heilige Nacht\", \"Hochfest der Geburt des Herrn\" (markiert im christlichen Glauben die Menschwerdung Gottes)"}]'::jsonb, 'Weinochtn oone Grissbaam und Liachdln warad fia mi undenkboa!'),
  ('adventszeit', 'Adventszeit', 'die', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Adventszeit', '[{"kategorie": "wörtlich", "text": "\"Adventszeit\" (vom mittelhochdeutschen \"adventszît\"=\"Ankunftszeit\")"}, {"kategorie": "rel.", "text": "\"Zeit der Ankunft\" (Zeitraum von etwa vier Wochen vor Weihnachten, in dem Christen die Ankunft Jesu Christi erwarten und sich innerlich auf das Weihnachtsfest vorbereiten. Sie ist zugleich eine Zeit der Besinnung, der Hoffnung und des Lichts in der Dunkelheit des Winters), (lateinisch): \"Adventus Domini\" (Ankunft des Herrn), \"Vorbereitungszeit auf Weihnachten\", [[de schdaade Zeit]]"}]'::jsonb, ''),
  ('adventskalender', 'Adventskalender', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Adventskalender', '[{"kategorie": "wörtlich", "text": "\"Adventskalender\" (Determinativkompositum aus \"Advent\"=\"Zeit der Ankunft\" und \"Kalender\"=\"Tageweiser\")"}, {"kategorie": "rel.", "text": "\"Vorweihnachtskalender\" (Kalender zur Zählung der Tage vom 1. bis zum 24. Dezember, also vom Beginn des Advents bis Heiligabend), \"Tageskalender im Advent\", \"Weihnachtskalender mit Türchen\" (dient traditionell dazu, die Wartezeit auf Weihnachten – insbesondere für Kinder – anschaulich und freudvoll zu gestalten. Hinter jedem der 24 Türchen, Säckchen, Kästchen oder Fenster verbirgt sich eine kleine Überraschung oder Botschaft, die täglich geöffnet wird)"}]'::jsonb, ''),
  ('adventkraunz', 'Adventkraunz', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Adventskranz', '[{"kategorie": "wörtlich", "text": "\"Adventskranz\" (Determinativkompositum aus \"Advent\"=\"Zeit der Ankunft\" und \"Kranz\"=\"Lichterkranz\")"}, {"kategorie": "rel.", "text": "\"Lichterkranz der Hoffnung\" (kreisförmiger Kranz aus Tannenzweigen, auf dem sich vier Kerzen befinden), \"Wegleuchter zum Weihnachtsfest\" (dient als christliches Symbol der Erwartung und Vorbereitung auf Weihnachten und hilft, die Adventszeit strukturiert zu begehen), \"Vierkerzenkranz\" (an jedem der vier Adventssonntage wird eine weitere Kerze entzündet – das Licht wächst, je näher Weihnachten rückt), \"Wichernkranz\" (wurde 1839 vom evangelischen Theologen Johann Hinrich Wichern in Hamburg eingeführt. Er verwendete einen Wagenrad-ähnlichen Holzkranz mit 20 kleinen und 4 großen Kerzen: kleine für Werktage, große für Sonntage im Advent. Ziel war es, den armen Waisenkindern im Rauhen Haus die Wartezeit bis Weihnachten sichtbar zu machen. Seit Anfang des 20. Jahrhunderts verbreitete sich der Kranz in evangelischen, später auch katholischen Haushalten)"}]'::jsonb, ''),
  ('oostasuundog', 'Oostasuundog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostersonntag', '[{"kategorie": "wörtlich", "text": "\"Ostersonntag\" (vom mittelhochdeutschen \"Ōsteren sūntag\"=\"Ostersonntag\")"}, {"kategorie": "rel.", "text": "katholischer Festtag (höchster und wichtigster Feiertag im Christentum ), \"erster Sonntag nach dem ersten Frühlingsvollmond\" (der an die Auferstehung Jesu Christi von den Toten – wie sie im Neuen Testament überliefert ist\" - erinnert)"}]'::jsonb, 'In da Oostanochd vuam Oostasuundog wiads Oostafeia auzind!'),
  ('oostamoondog', 'Oostamoondog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostermontag', '[{"kategorie": "wörtlich", "text": "\"Ostermontag\" (vom mittelhochdeutschen \"Ōsteren mântac\"=\"Ostersonntag\")"}, {"kategorie": "rel.", "text": "katholischer Festtag (zweite Feiertag des Osterfestes direkt nach dem [[Ostersonntag]]), \"Tag des Emmaus-Gangs\" (Gang nach Emmaus, bei dem der auferstandene Christus zwei Jüngern begegnet, ohne dass sie ihn sofort erkennen)"}]'::jsonb, 'Aum Oostamoondog gedenkn de Christn in Jesus, wiara aan Toog noch seina Aufeaschdeehung vua zwaa von seine Jünga easchiinan is!'),
  ('pfingstn', 'Pfingstn', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pfingsten', '[{"kategorie": "wörtlich", "text": "\"Pfingstfest\" (vom mittelhochdeutschen  \"pfingesten\"=\"Pfingsten\")"}, {"kategorie": "rel.", "text": "\"Pfingsten\" (christliches Hochfest, das 50 Tage nach Ostern gefeiert wird), \"Fest des Heiligen Geistes\" (vollendet die Heilsgeschichte von Ostern: Nach der Auferstehung Jesu sendet Gott den Heiligen Geist – als bleibende Gegenwart Christi in der Welt), \"Pentecoste\" (vom griechischen „pentēkostḗ“= „der fünfzigste [Tag nach Ostern]“, gilt als die Geburtsstunde der Kirche), \"Fest der Ausgießung des Geistes\" (erinnert an die Ausgießung des Heiligen Geistes auf die Jünger Jesu - vgl. Apostelgeschichte 2)"}]'::jsonb, 'Pfingstn soi uns draun erinnan, dass Gottes Geist unta uns leebd und wiakd!'),
  ('pfingstsuundog', 'Pfingstsuundog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pfingstsonntag', '[{"kategorie": "wörtlich", "text": "\"Pfingstsonntag\" (vom mittelhochdeutschen \"pfingest suntac\"=\"Pfingstsonntag\")"}, {"kategorie": "rel.", "text": "\"Hochfest von Pfingsten\" (Haupttag des Pfingstfestes, wird 50 Tage nach [[Ostersonntag]] gefeiert), \"Festtag des Heiligen Geistes\" (erinnert an die Ausgießung des Heiligen Geistes auf die Jünger Jesu in Jerusalem - vgl. Apostelgeschichte 2), \"Tag der Geistsendung\" (dieser Tag gilt als die Geburtsstunde der Kirche)"}]'::jsonb, 'Aum Pfingstsuundog schmück ma in Hauseingaung mit frische Biaknzweig!'),
  ('pfingstmoondog', 'Pfingstmoondog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pfingstmontag', '[{"kategorie": "wörtlich", "text": "\"Pfingstmontag\" (vom mittelhochdeutschen \"pfingest mântac\"=\"Pfingstmontag\")"}, {"kategorie": "rel.", "text": "\"Zweiter Tag des Hochfests von Pfingsten\" (zweiter Tag des Pfingstfestes, wird 51 Tage nach [[Ostersonntag]] gefeiert), \"Festtag der Geistausbreitung\" (erinnert an die Ausgießung des Heiligen Geistes auf die Jünger Jesu in Jerusalem - vgl. Apostelgeschichte 2), \"Tag nach der Geistsendung\" (d.h. \"2. Tag der Pfingstoktav\", 1 Tag nach [[Pfingstsonntag]])"}]'::jsonb, 'Pfingstmoondog is da Toog, aun dem da Geist auf leisn Fliagln weidaziagd!'),
  ('grissdoog', 'Grissdoog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Christtag', '[{"kategorie": "wörtlich", "text": "\"Christtag\" (vom mittelhochdeutschen \"kristes tag\"=\"Christtag\")"}, {"kategorie": "rel.", "text": "Erster Weihnachtsfeiertag (25. Dezember, zentraler christlicher Feiertag. Er bildet zusammen mit dem [[Heiligen]] Abend [24. Dezember] und dem [[Stefanitag]] [26. Dezember] das Weihnachtsfest.), Fest der Geburt Christi, \"Hochfest der Geburt des Herrn\" (der Christtag feiert die Menschwerdung Gottes in Jesus Christus, in der Liturgie ist es das Hochfest der Geburt des Herrn)"}]'::jsonb, 'Da Grissdoog is mea ois nuara Datum - es is a Moment da Einkea und des Wundas!'),
  ('schdefaanidoog', 'Schdefaanidoog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Stefanitag', '[{"kategorie": "wörtlich", "text": "\"Stefanitag\" (vom mittelhochdeutschen \"Stephanes tag\"=\"Stefanitag\")"}, {"kategorie": "rel.", "text": "Zweiter Weihnachtsfeiertag (26. Dezember), \"Festtag des heiligen Stephan(us)\" (Hochfest und Märtyrertag in der römisch-katholischen und orthodoxen Kirche. Stephanus war einer der ersten sieben Diakone), \"Sankt Stephans Tag\" (Gedenktag des heiligen Stephanus, der in der Apostelgeschichte als erster Märtyrer [„Erzmärtyrer“] des Christentums dargestellt wird. Er wurde wegen seines Glaubens gesteinigt)"}]'::jsonb, 'Aum Schdefaanidoog brechn de Bauan scho früü aum Moagn zum Schdefaaniritt duachs vaschneide Toi auf!'),
  ('suewoeoesta', 'Süwöösta', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Silvester', '[{"kategorie": "wörtlich", "text": "\"Silvestertag\" (vom mittelhochdeutschen \"Sankte Siluesters tac\"=\"Tag des Heiligen Silvester\")"}, {"kategorie": "rel.", "text": "\"Silvestertag\" (31. Dezember, letzter Tag des Kalenderjahres, der dem Gedenktag des heiligen Papstes Silvester I. gewidmet ist. Er wird sowohl kirchlich als auch weltlich begangen), \"Tag des Heiligen Silvester\" (Gedenktag Papst Silvesters I., letzter Tag im Kirchenjahr), \"Sankt-Silvester-Tag\" (Gedenktag des heiligen Silvester I., Papst von 314–335, unter dessen Pontifikat das Christentum im Römischen Reich anerkannt wurde), \"Silvesterfest\" (in der römisch-katholischen Kirche ist es ein heiliger Tag, oft mit einem Dankgottesdienst zum Jahresabschluss verbunden [„Jahresschlussmesse“])"}]'::jsonb, ''),
  ('prosit', 'Prosit!', '', '', '', 'Grundwortschatz Wienerisch', 'Prosit!', '[{"kategorie": "wörtlich", "text": "\"Prosit!\" (vom lateinischen \"prosit\"=\"es möge zuträglich sein\")"}, {"kategorie": "allg.", "text": "\"Prost!\", \"Zum Wohl!\", \"Auf dein/euer Wohl!“, \"Hoch die Gläser!\", \"Cheers!\" (Trinkspruch, der traditionell beim gemeinsamen Anstoßen ausgesprochen wird, wobei \"Prosit\" ursprünglich auch in klösterlichen und gelehrten Kreisen beim Weintrinken oder nach Segenssprüchen gesagt wurde – mit einer stets feierlichen Note)"}]'::jsonb, ''),
  ('neijoasdoog', 'Neijoasdoog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Neujahrstag', '[{"kategorie": "wörtlich", "text": "\"Neujahrstag\" (vom mittelhochdeutschen \"niuwen jâres tac\"=\"Tag des neuen Jahres\")"}, {"kategorie": "rel.", "text": "\"erster Tag im neuen Jahr\" (1. Jänner, der erste Tag des Gregorianischen Kalendersjahres und zugleich ein weltlich wie religiös bedeutsamer Feiertag), \"Hochfest der Gottesmutter Maria\" (christlicher Feiertag, der am 1. Januar gefeiert wird. Es ist eines der höchsten Marienfeste in der römisch-katholischen Kirche und bildet den liturgischen Abschluss der Weihnachtsoktav), \"Oktavtag von Weihnachten\" (der achte Tag nach dem Hochfest der Geburt des Herrn [Weihnachten] – also der 1. Januar. In der römisch-katholischen Liturgie ist dies der Abschluss der Weihnachtsoktav, einer festlichen achttägigen Feierperiode)"}, {"kategorie": "allg.", "text": "\"Neujahr\", \"Jahresanfang\", \"erster Feiertag im neuen Jahr\""}]'::jsonb, 'Da Neijoasdoog is da Moagn danooch - waunnst zwischn Böllahüüsn, leere Sektfloschn und an schlechtn Gwissn aufwochst!'),
  ('faschn', 'faschn', '', '', '', 'Grundwortschatz Wienerisch', 'faschen', '[{"kategorie": "wörtlich", "text": "\"mit einer Binde umwickeln\" (vom mittelhochdeutschen \"fasch\"=\"Binde\")"}, {"kategorie": "allg.", "text": "einen Stützverband anlegen, bandagieren, verbinden, komprimieren"}, {"kategorie": "technisch", "text": "eine Fensterbordüre anbringen, eine Türbordüre anbringen, mit einer Zierbinde versehen, einfassen, umrahmen"}, {"kategorie": "", "text": "ein Scharnierband anbringen, eine Türscharnier anbringen, einlassen, einfassen, einfräsen"}]'::jsonb, 'Da Saani hod ma ''n Knechl gfascht, und de Schwöllung is daunn aa glei zruckgaungan!'),
  ('fatschn', 'fatschn', '', '', '', 'Grundwortschatz Wienerisch', 'fatschen', '[{"kategorie": "wörtlich", "text": "\"mit einer Binde umwickeln\" (vom mittelhochdeutschen \"fasch\"=\"Binde\")"}, {"kategorie": "allg.", "text": "einen Stützverband anlegen, bandagieren, verbinden, komprimieren"}, {"kategorie": "technisch", "text": "eine Fensterbordüre anbringen, eine Türbordüre anbringen, mit einer Zierbinde versehen, einfassen, umrahmen"}, {"kategorie": "", "text": "ein Scharnierband anbringen, eine Türscharnier anbringen, einlassen, einfassen, einfräsen"}]'::jsonb, 'Da Saani hod ma ''n Knechl gfaschtnd, und de Schwöllung is daunn aa glei zruckgaungan!'),
  ('saani', 'Saani', 'der', '', '', 'Krank & kuriert auf Wienerisch', 'Sani', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Sanitäter\" (vom lateinischen \"sanitas\"=\"Gesundheit\")"}, {"kategorie": "med.", "text": "Rettungssanitäter, Notfallsanitäter, Ersthelfer, medizinischer Erstversorger"}]'::jsonb, ''),
  ('faulenza', 'Faulenza', 'der', '', '', 'Grundwortschatz Wienerisch', 'Faulenzer', '[{"kategorie": "wörtlich", "text": "\"faule Person\" (vom mittelhochdeutschen \"vūlezen\"=\"faulig riechen\")"}, {"kategorie": "allg.", "text": "\"fauler Mensch\", Müßiggänger, Nichtstuer, \"Chiller\", \"Couchpotato\", \"Schlafbär\", [[Owezaara]]"}, {"kategorie": "Schülerjargon", "text": "Linienspiegel, Schönschreibhilfe, Linienblatt (Blattunterlage mit vorgezeichneten Linien, um auf dem darüberliegenden Blatt gerade schreiben zu können)"}]'::jsonb, 'Da greessde Faulenza bei uns im Haus is da Hund - dea schloofd 18 Schdund aum Toog!'),
  ('feeba', 'Feeba', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Feber', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Februar\" (vom lateinischen \"mensis februarius\"=\"Reinigungsmonat\", d.h. ursprünglich der letzte Monat des altrömischen Jahres, welches mit dem 1. März beginnt und unmittelbar auf den Monat nach den Reinigungs- und Sühneopfern folgt)"}, {"kategorie": "allg.", "text": "der zweite Monat im Kalenderjahr"}]'::jsonb, ''),
  ('fechta', 'Fechta', 'der', '', '', 'Grundwortschatz Wienerisch', 'Fechter', '[{"kategorie": "wörtlich", "text": "\"der ums Überleben Kämpfende\" (vom mittelhochdeutschen \"vehten\"=\"kämpfen\")"}, {"kategorie": "allg., Sport", "text": "Fechter, Degenfechter, Säbelfechter"}, {"kategorie": "hist.", "text": "Bettler, Straßenbettler, Almosenempfänger, [[Palanzer]], [[Grießler]]"}]'::jsonb, 'Ois Fechta muassd ned nua schnöö sei, sondan aa strategisch denkn!'),
  ('feidl', 'Feidl', 'der', '', '', 'Grundwortschatz Wienerisch', 'Feitel', '[{"kategorie": "wörtlich", "text": "\"Messer\" (vom mittelhochdeutschen \"fitelîn\"=\"kleines Messer\")"}, {"kategorie": "allg.", "text": "kleines Messer, Faltmesser, Taschenmesser, Klappmesser, [[Schnapper]], [[Mau]]"}, {"kategorie": "Koseform für", "text": "\"Veit\" (männlicher Vorname, auch \"Vitus\")"}, {"kategorie": "scherzhaft für", "text": "\"Schneidwerkzeug\", Penis, Schwanz, \"Schniedel\", [[Nudel]], [[Beidl]], [[Gurken]], [[Futraspel]]"}]'::jsonb, 'Pass auf, Oida, sunst foar I da min Feidl iwas Gsichd!'),
  ('feidln', 'feidln', '', '', '', 'Grundwortschatz Wienerisch', 'feiteln', '[{"kategorie": "wörtlich", "text": "\"mit einem  Messer schneiden\" (vom mittelhochdeutschen \"fitelen\"=\"fitzeln\")"}, {"kategorie": "allg.", "text": "mit einem stumpfen Messer säbeln, sägen, schneiden, schnitzen, schaben"}]'::jsonb, 'Da Opa hockd in gaunz Toog im Goatn und feidld aun sein Schbaziaschdock!'),
