  ('fetzn', 'fetzn', '', '', '', 'Grundwortschatz Wienerisch', 'fetzen', '[{"kategorie": "wörtlich", "text": "\"etwas in Fetzen reißen\" (vom mittelhochdeutschen \"vetzen\"=\"in Fetzen reißen\")"}, {"kategorie": "allg.", "text": "etwas (mit großer Kraft) abreißen, zerreißen"}, {"kategorie": "fig.", "text": "schlampig oder eilig arbeiten, unschön schreiben, schmieren, schludern"}, {"kategorie": "", "text": "sich mit großer Schnelligkeit irgendwohin bewegen, schnellfahren, rasen, sausen"}, {"kategorie": "fig.", "text": "\"sich in Fetzen reißen\", (sich) streiten, sich zanken, [[sich]] hackeln"}, {"kategorie": "fig.", "text": "\"sich das Maul zerfetzen\", große Töne spucken, auf den Putz hauen, prahlen, angeben, protzen"}]'::jsonb, 'De Tapeedn ghean gfetzd!'),
